const dayKey=date=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const todayKey=()=>dayKey(new Date());
const shiftDay=(key,offset)=>{const date=new Date(`${key}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+offset);return dayKey(date)};
const weekDay=key=>new Date(`${key}T12:00:00Z`).getUTCDay();
data.dailyWater??={};data.studentGoals??={};data.excusedDays??={};
function goalsFor(id){return data.studentGoals[id]||{water:2000,weekly:3,days:[],since:todayKey()}}
function waterFor(id,key=todayKey()){return data.dailyWater[id]?.[key]||0}
function trainedOn(id,key){return data.logs.some(l=>l.student===id&&dayKey(new Date(l.date))===key)}
function weekDays(){const now=todayKey(),sinceMonday=(weekDay(now)+6)%7;return Array.from({length:7},(_,i)=>shiftDay(now,i-sinceMonday))}
function missedDays(id){const g=goalsFor(id);return Array.from({length:14},(_,i)=>shiftDay(todayKey(),-14+i)).filter(key=>key>=g.since&&g.days.includes(weekDay(key))&&!trainedOn(id,key)&&!data.excusedDays[id]?.[key])}
function weekCount(id){return weekDays().filter(key=>trainedOn(id,key)).length}
function studentSelector(){return `<select aria-label="Selecionar aluno" onchange="selectStudent(this.value)">${visibleStudents().map(s=>`<option value="${s.id}" ${s.id===student?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`}
function weeklyStrip(id){const g=goalsFor(id);return `<div class="habit-week">${weekDays().map(key=>`<div class="habit-day ${trainedOn(id,key)?'complete':key===todayKey()?'today':''}"><small>${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'][weekDay(key)]}</small><span>${trainedOn(id,key)?'✓':g.days.includes(weekDay(key))?'•':'—'}</span><small>${key.slice(8)}</small></div>`).join('')}</div>`}
function goalCards(){const g=goalsFor(student),water=waterFor(student),count=weekCount(student),pct=Math.min(100,Math.round(water/g.water*100)),trained=trainedOn(student,todayKey()),scheduled=g.days.includes(weekDay(todayKey()));return `<div class="goal-grid"><section class="card water-card"><div class="row"><span class="goal-icon">◉</span><span class="tag">META DE HOJE</span></div><h2>Um gole de cada vez.</h2><p>Água registrada hoje</p><div class="goal-value">${(water/1000).toLocaleString('pt-BR')} <small>/ ${(g.water/1000).toLocaleString('pt-BR')} L</small></div><div class="goal-meter" role="progressbar" aria-label="Meta de água" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><p>${pct===100?'✓ Meta de água cumprida!':`${Math.max(0,g.water-water)} ml para sua meta`}</p><div class="water-actions"><button class="primary" onclick="logWater(250)">+ 250 ml</button><button onclick="logWater(500)">+ 500 ml</button><button aria-label="Desfazer último registro de água" onclick="undoWater()">↶</button></div><p class="note">Meta personalizável. Ajuste conforme sua orientação profissional.</p></section><section class="card"><div class="row"><span class="goal-icon">↗</span><span class="tag">CONSISTÊNCIA</span></div><h2>Sua semana em movimento.</h2><div class="goal-value">${count} <small>/ ${g.weekly} dias de treino</small></div>${weeklyStrip(student)}<p>${count>=g.weekly?'✓ Meta semanal cumprida!':`Faltam ${Math.max(0,g.weekly-count)} dias de treino para sua meta.`}</p><span class="tag">${trained?'✓ TREINO DE HOJE CONCLUÍDO':scheduled?'HOJE TEM TREINO':'SEU RITMO, SUA EVOLUÇÃO'}</span><button class="primary full-button" onclick="go('treinos')">${trained?'Ver meu treino':'Vamos treinar'} ↗</button></section></div>`}
function studentAlerts(){const missed=missedDays(student);return missed.length?`<section class="attendance-alert" role="status"><b>Seu treino está esperando por você.</b><p>${missed.length} treino(s) previsto(s) sem registro nos últimos 14 dias. Se você treinou ou precisou faltar, converse com seu personal.</p><button onclick="go('interacao')">Conversar com personal</button></section>`:''}
function studentHome(){const g=goalsFor(student);return heading('SEU DIA NA HPE FORÇA BRUTA',`Olá, ${esc(current().name.split(' ')[0])}. 👋`,'Pequenas metas. Uma versão mais forte de você.',`<button onclick="editGoals(false)">Ajustar metas</button>`)+studentAlerts()+goalCards()+`<section class="card daily-checklist"><h2>Suas conquistas de hoje</h2><div class="listrow"><span class="goal-icon">${waterFor(student)>=g.water?'✓':'○'}</span><div><b>Completar a meta de água</b><p>${waterFor(student)} de ${g.water} ml registrados</p></div></div><div class="listrow"><span class="goal-icon">${trainedOn(student,todayKey())?'✓':'○'}</span><div><b>${g.days.includes(weekDay(todayKey()))?'Concluir o treino programado':'Manter a rotina da semana'}</b><p>${trainedOn(student,todayKey())?'Treino de hoje registrado. Boa!':g.days.includes(weekDay(todayKey()))?'Seu personal programou treino para hoje.':'Confira o plano e respeite os dias de recuperação.'}</p></div></div><p class="note">Os registros são salvos neste navegador. Não há sincronização entre aparelhos nesta versão.</p></section>`}
function dailyGraph(id){const g=goalsFor(id),days=Array.from({length:7},(_,i)=>shiftDay(todayKey(),i-6));return `<div class="daily-chart" role="img" aria-label="Água e presença nos últimos sete dias">${days.map(key=>{let pct=Math.min(100,waterFor(id,key)/g.water*100),trained=trainedOn(id,key),missed=missedDays(id).includes(key);return `<div class="chart-column"><div class="chart-track"><div class="chart-bar" style="height:${pct}%" title="${waterFor(id,key)} ml de água"><span>${waterFor(id,key)} ml</span></div></div><b>${key.slice(8)}/${key.slice(5,7)}</b><span class="attendance-dot ${trained?'present':missed?'absent':''}" title="${trained?'Treino registrado':missed?'Treino previsto sem registro':'Sem treino registrado'}">${trained?'✓':missed?'!':'—'}</span></div>`}).join('')}</div><div class="chart-legend"><span>▰ Água / meta diária</span><span>✓ Treino registrado</span><span>! Previsto sem registro</span></div>`}
function absencePanel(){const alerts=visibleStudents().flatMap(s=>missedDays(s.id).map(key=>({s,key})));return `<section class="card absence-panel"><div class="row"><h2>Alertas de presença</h2><span class="tag">${alerts.length} PENDÊNCIAS</span></div><p>Treinos programados em dias já encerrados, sem conclusão registrada.</p>${alerts.length?alerts.map(({s,key})=>`<div class="absence-row"><div><b>${esc(s.name)}</b><p>${key.split('-').reverse().join('/')} · Treino previsto sem registro</p></div><button onclick="selectStudent(${s.id});go('interacao')">Ver conversa</button><button onclick="excuseDay(${s.id},'${key}')">Justificar</button></div>`).join(''):'<div class="empty">✓ Nenhuma falta detectada no período.<br>Configure os dias de treino de cada aluno para acompanhar a presença.</div>'}<p class="note">Alertas internos, baseados nos registros locais dos últimos 14 dias. Não enviam notificações fora do app.</p></section>`}
function coachHome(){const g=goalsFor(student),missed=missedDays(student);return heading('ACOMPANHAMENTO DIÁRIO','Cada hábito conta.','Veja os registros de água, treino e presença de seus alunos.',studentSelector())+`<div class="grid stats"><div class="card stat"><p>Água hoje · ${esc(current().name)}</p><strong>${waterFor(student)} <small>ml</small></strong><small>Meta: ${g.water} ml</small></div><div class="card stat"><p>Dias de treino nesta semana</p><strong>${weekCount(student)} / ${g.weekly}</strong><small>Uma sessão por dia no indicador</small></div><div class="card stat"><p>Treinos previstos sem registro</p><strong>${missed.length}</strong><small>Últimos 14 dias · dias encerrados</small></div></div><section class="card"><div class="row"><div><span class="eyebrow">ÚLTIMOS 7 DIAS</span><h2>${esc(current().name)} · hábitos e presença</h2></div><button class="primary" onclick="editGoals(true)">Programar metas e dias</button></div>${dailyGraph(student)}<p class="note">Dias sem registros ficam vazios. A ausência só é calculada a partir da data em que a programação foi criada.</p></section>${absencePanel()}`}
let waterHistory=[];
window.logWater=amount=>{if(role!=='aluno'||![250,500].includes(amount))return;const key=todayKey();data.dailyWater[student]??={};waterHistory.push({student,key,before:waterFor(student,key)});data.dailyWater[student][key]=waterFor(student,key)+amount;save();render();toast(`+ ${amount} ml registrados. Boa!`)};
window.undoWater=()=>{const item=waterHistory.at(-1);if(!item||item.student!==student||item.key!==todayKey()){toast('Nenhum registro recente para desfazer.');return}waterHistory.pop();data.dailyWater[student][item.key]=item.before;save();render();toast('Último registro de água desfeito.')};
window.editGoals=coach=>{if(coach&&role!=='personal')return;const id=student,g=goalsFor(id);modal(`<h2>${coach?'Metas e programação':'Suas metas'}</h2><p>${esc(current().name)}</p><form id="goalsForm"><label>Meta diária de água (ml)<input type="number" name="water" min="250" max="10000" step="50" value="${g.water}" required></label><label>Meta semanal (dias de treino)<input type="number" name="weekly" min="1" max="7" value="${g.weekly}" required></label>${coach?`<fieldset><legend>Dias de treino programados</legend><div class="schedule-days">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((day,i)=>`<label><input type="checkbox" name="days" value="${i}" ${g.days.includes(i)?'checked':''}>${day}</label>`).join('')}</div></fieldset><p class="note">A programação começa hoje. Alertas surgem após o dia previsto encerrar. Alterar os dias reinicia o período de acompanhamento.</p>`:''}<button class="primary">Salvar metas</button></form>`);$('#goalsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),water=+f.get('water'),weekly=+f.get('weekly');if(water<250||water>10000||weekly<1||weekly>7)return;const days=coach?f.getAll('days').map(Number):g.days;const changed=JSON.stringify(days)!==JSON.stringify(g.days);data.studentGoals[id]={water,weekly,days,since:changed?todayKey():g.since};save();$('#modal').close();render();toast('Metas atualizadas.')}};
window.excuseDay=(id,key)=>{if(role!=='personal')return;data.excusedDays[id]??={};data.excusedDays[id][key]=true;save();render();toast('Ausência marcada como justificada.')};
const mobileRender=render;render=function(){mobileRender();if(page==='inicio')$('#content').innerHTML=role==='aluno'?studentHome():coachHome();if(page==='metas'&&role==='aluno')$('#content').innerHTML=studentHome();if(page==='evolucao'&&role==='personal')$('#content').insertAdjacentHTML('afterbegin',`<section class="card progress-extra"><h2>Acompanhamento diário · ${esc(current().name)}</h2>${studentSelector()}${dailyGraph(student)}<button onclick="editGoals(true)">Programar dias de treino</button></section>`);if(role==='aluno')$('#nav').insertAdjacentHTML('beforeend',`<button class="${page==='metas'?'active':''}" onclick="go('metas')">◉ &nbsp; Minhas metas</button>`)};


